def process(self, d):
    d = self.tokenizer.encode(d[self.text_key])
    if d[-1] != self.tokenizer.eos_token_id:
        d.append(self.tokenizer.eos_token_id)
    return (d, 0)

def process(self, d):
    messages = d[self.chat_key]
    tools = d.get("tools", None)
    tokens = self.tokenizer.apply_chat_template(
        messages,
        tools=tools,
        return_dict=False,
    )
    if self.mask_prompt:
        add_generation_prompt = messages[-1].get("role") == "assistant"
        offset = len(
            self.tokenizer.apply_chat_template(
                messages[:-1],
                tools=tools,
                add_generation_prompt=add_generation_prompt,
                return_dict=False,
            )
        )
        return (tokens, offset)
    else:
        return (tokens, 0)

def process(self, d):
    tools = d.get("tools", None)
    messages = [
        {"role": "user", "content": d[self.prompt_key]},
        {"role": "assistant", "content": d[self.completion_key]},
    ]
    tokens = self.tokenizer.apply_chat_template(
        messages, tools=tools, return_dict=False
    )
    if self.mask_prompt:
        offset = len(
            self.tokenizer.apply_chat_template(
                messages[:-1],
                tools=tools,
                add_generation_prompt=True,
                return_dict=False,
            )
        )
        return (tokens, offset)

    return (tokens, 0)

def __getitem__(self, idx: int):
    if self._proc_data[idx] is None:
        self._proc_data[idx] = self._data.process(self._data[idx])
    return self._proc_data[idx]

def create_dataset(
    data,
    tokenizer: PreTrainedTokenizer,
    config,
):
    mask_prompt = getattr(config, "mask_prompt", False)
    prompt_feature = getattr(config, "prompt_feature", "prompt")
    text_feature = getattr(config, "text_feature", "text")
    completion_feature = getattr(config, "completion_feature", "completion")
    chat_feature = getattr(config, "chat_feature", "messages")
    sample = data[0]
    if prompt_feature in sample and completion_feature in sample:
        return CompletionsDataset(
            data, tokenizer, prompt_feature, completion_feature, mask_prompt
        )
    elif chat_feature in sample:
        return ChatDataset(
            data, tokenizer, chat_key=chat_feature, mask_prompt=mask_prompt
        )
    elif text_feature in sample:
        if mask_prompt:
            raise ValueError("Prompt masking not supported for text dataset.")
        return TextDataset(data, tokenizer, text_key=text_feature)
    else:
        raise ValueError(
            "Unsupported data format, check the supported formats here:\n"
            "https://github.com/ml-explore/mlx-lm/blob/main/mlx_lm/LORA.md#Data."
        )

def load_dataset(args, tokenizer: PreTrainedTokenizer):
    if getattr(args, "hf_dataset", False):
        train, valid, test = load_custom_hf_dataset(args, tokenizer)
    else:
        data_path = Path(args.data)
        if data_path.exists():
            train, valid, test = load_local_dataset(data_path, tokenizer, args)
        else:
            rprint(f"Loading Hugging Face dataset {args.data}.")
            train, valid, test = load_hf_dataset(args.data, tokenizer, args)

    if args.train and len(train) == 0:
        raise ValueError(
            "Training set not found or empty. Must provide training set for fine-tuning."
        )
    if args.train and len(valid) == 0:
        rprint(
            "Warning: Validation set not found or empty. Training will proceed without validation."
        )
    if args.test and len(test) == 0:
        raise ValueError(
            "Test set not found or empty. Must provide test set for evaluation."
        )
    return train, valid, test

def iterate_batches(
    dataset,
    batch_size,
    max_seq_length,
    loop=False,
    seed=None,
    comm_group=None,
):
    # Sort by length:
    if isinstance(dataset, CacheDataset):
        len_fn = lambda idx: dataset.itemlen(idx)
    else:
        len_fn = lambda idx: len(dataset[idx][0])
    idx = sorted(range(len(dataset)), key=len_fn)
    if len(dataset) < batch_size:
        raise ValueError(
            f"Dataset must have at least batch_size={batch_size}"
            f" examples but only has {len(dataset)}."
        )

    # If running in distributed mode (N machines) then each one should skip N-1
    # samples
    if comm_group is not None:
        offset = comm_group.rank()
        step = comm_group.size()
    else:
        offset = 0
        step = 1
    if batch_size % step != 0:
        raise ValueError("The batch size must be divisible by the number of workers")

    # Make the batches:
    batch_idx = [
        idx[i + offset : i + offset + batch_size : step]
        for i in range(0, len(idx) - batch_size + 1, batch_size)
    ]
    if seed is not None:
        np.random.seed(seed)
    while True:
        indices = np.random.permutation(len(batch_idx))
        for i in indices:
            batch = [dataset[j] for j in batch_idx[i]]
            if len(batch[0]) == 2:
                batch, offsets = zip(*batch)
            else:
                offsets = [0] * len(batch)
            lengths = [len(x) for x in batch]
            if max(lengths) > max_seq_length:
                rprint(
                    f"[WARNING] Some sequences are longer than {max_seq_length} tokens. "
                    f"The longest sentence {max(lengths)} will be truncated to {max_seq_length}. "
                    "Consider pre-splitting your data to save memory."
                )

            # Pad to one plus nearest multiple of pad_to or the maximum length
            pad_to = 32
            max_length_in_batch = 1 + pad_to * ((max(lengths) + pad_to - 1) // pad_to)
            max_length_in_batch = min(max_length_in_batch, max_seq_length)

            batch_arr = np.zeros((batch_size // step, max_length_in_batch), np.int32)

            for j in range(batch_size // step):
                truncated_length = min(lengths[j], max_seq_length)
                batch_arr[j, :truncated_length] = batch[j][:truncated_length]
                lengths[j] = (
                    truncated_length  # Update lengths to match truncated lengths
                )
            batch = mx.array(batch_arr)
            yield batch, mx.array(list(zip(offsets, lengths)))

        if not loop:
            break

def load_adapter_weights(
    model: nn.Module, *, path: str | Path, fine_tune_type: str
) -> None:
    """Load adapter weights into a model that already has its LoRA or DoRA layers."""
    weights = mx.load(str(path))
    params = dict(tree_flatten(model.parameters()))
    if fine_tune_type == "full":
        allowed = params
    else:
        allowed = {
            name: param
            for name, param in params.items()
            if name.rsplit(".", 1)[-1] in _ADAPTER_LEAVES
        }
        weights = _match_by_layer(weights, allowed)
    errors: list[str] = []
    for name, w in weights.items():
        if name not in allowed:
            errors.append(f"  {name}: not an adapter parameter in the model")
        elif w.shape != allowed[name].shape:
            errors.append(
                f"  {name}: adapter shape {tuple(w.shape)} does not match "
                f"model parameter shape {tuple(allowed[name].shape)}"
            )
    if errors:
        raise ValueError(
            f"Adapter at {path} contains incompatible tensors:\n" + "\n".join(errors)
        )
    model.load_weights(list(weights.items()), strict=False)
